
<template>

<div class="container" style="max-width: 500px;"> <div class="card"> <h3 class="form-title">个人中心</h3> <p v-if="msg" :class="isError ? 'error' : 'tip'">{{ msg }}</p> <label class="tip">用户名</label> <input :value="store.user?.username" disabled /> <label class="tip">昵称</label> <input v-model="form.nickname" /> <label class="tip">头像 URL</label> <input v-model="form.avatar" /> <button :disabled="saving" @click="save"> {{ saving ? '保存中...' : '保存资料' }} </button> </div> <div class="card"> <h3 class="form-title">修改密码</h3> <p v-if="pwdMsg" :class="pwdError ? 'error' : 'tip'">{{ pwdMsg }}</p> <input v-model="pwd.oldPassword" type="password" placeholder="原密码" /> <input v-model="pwd.newPassword" type="password" placeholder="新密码（至少6位）" /> <button :disabled="changing" @click="changePwd"> {{ changing ? '提交中...' : '修改密码' }} </button> </div> </div> </template><script setup> import { reactive, ref, onMounted } from 'vue'; import { userApi } from '../api'; import { useUserStore } from '../stores/user'; const store = useUserStore(); const form = reactive({ nickname: '', avatar: '' }); const pwd = reactive({ oldPassword: '', newPassword: '' }); const msg = ref(''); const isError = ref(false); const saving = ref(false); const pwdMsg = ref(''); const pwdError = ref(false); const changing = ref(false); onMounted(async () => { await store.fetchMe(); form.nickname = store.user?.nickname || ''; form.avatar = store.user?.avatar || ''; }); async function save() { msg.value = ''; saving.value = true; try { const res = await userApi.updateMe({ ...form }); store.user = res.data; localStorage.setItem('user', JSON.stringify(res.data)); msg.value = '保存成功'; isError.value = false; } catch (e) { msg.value = e.message || '保存失败'; isError.value = true; } finally { saving.value = false; } } async function changePwd() { pwdMsg.value = ''; if (!pwd.oldPassword || !pwd.newPassword) { pwdMsg.value = '请填写完整'; pwdError.value = true; return; } changing.value = true; try { await userApi.changePassword({ ...pwd }); pwdMsg.value = '密码修改成功'; pwdError.value = false; pwd.oldPassword = ''; pwd.newPassword = ''; } catch (e) { pwdMsg.value = e.message || '修改失败'; pwdError.value = true; } finally { changing.value = false; } } </script>
